// 只认可声明已选原Offer与真实半日Action；外部旧accept和无目录的伪具名source均拒绝。
#include "task_personal_acceptance_services.hpp"
#include "task_personal_acceptance_detail.hpp"
namespace hanmo::resident {
Status validate_task_personal_acceptance_services(const CommonStore& c,const TaskState& tasks,const TaskCatalog& catalog,const TaskPersonalAcceptanceState* state,const TaskPersonalAcceptanceServices* service){if(bool(state)!=(service!=nullptr))return common_failure("TaskPersonalAcceptanceServicesMismatch");if(!service)return common_success();const auto& x=service->sources;if(state!=&x.state||&c!=&x.common||&tasks!=&x.tasks||&catalog!=&x.task_catalog)return common_failure("TaskPersonalAcceptanceCandidateRequired");return common_success();}
// 早期仅作不可变选择与原Task反向覆盖，晚期才按真实Known/控制/生命重读完整接受史。
Status validate_task_personal_acceptance_task_coverage(const TaskState& tasks,const TaskPersonalAcceptanceCatalog* catalog,const TaskPersonalAcceptanceState* state){if(bool(catalog)!=(state!=nullptr))return common_failure("TaskPersonalAcceptanceProfileMismatch");if(!catalog)return common_success();std::set<StableId> covered;for(const auto& row:state->starts.rows())if(!covered.insert(row.second.task_id).second)return common_failure("DuplicateTaskPersonalAcceptanceStart",row.first);for(const auto& row:tasks.tasks.rows())if(!row.second.contract_id&&!row.second.offer_ref&&task_personal_acceptance_policy(*catalog,row.second.offer_id)&&!covered.count(row.first))return common_failure("TaskPersonalAcceptanceOriginalTaskSourceRequired",row.first);return common_success();}
Status validate_task_personal_acceptance_action_shape(const CommonStore& c,const TaskState& tasks,const TaskPersonalAcceptanceState& state,const ActionCoreView& action,const TaskAction& params){using namespace personal_acceptance_detail;const auto* s=start_for_action(state,action.id);const auto* task=tasks.tasks.find(params.task_id);const auto* head=s?c.state().facts.find(s->fact_id):nullptr;if(state.version!=1||!s||!task||!head||head->kind!=task_personal_acceptance_started_kind||head->domain!=task_personal_acceptance_module||params.source_kind!=std::optional<StableId>{task_personal_acceptance_source_kind}||action.kind!="accept_offer"||s->task_id!=task->id||s->offer_id!=params.offer_id||task->offer_id!=params.offer_id||task->assignee!=action.actor_id||s->carrier_actor_id!=action.actor_id||s->started_tick!=action.start_tick||s->sender_actor_id!=params.context.provider_actor_id||params.reward||action.participants!=std::vector<StableId>{s->carrier_actor_id,s->sender_actor_id}||!context(params.context,s->sender_declaration.declaration.meeting.context))return common_failure("TaskPersonalAcceptanceActionSourceRequired",action.id);return common_success();}
Status task_personal_acceptance_original_preview_gate(const TaskPersonalAcceptanceCatalog* selected,const TaskCommand& command){if(command.source_kind==std::optional<StableId>{task_personal_acceptance_source_kind})return common_failure("TaskPersonalAcceptanceDedicatedCommandRequired");if(command.kind=="accept_offer"&&selected&&(!command.offer_ref||command.offer_ref->kind==OfferRef::Kind::authored)&&task_personal_acceptance_policy(*selected,task_command_offer(command).id))return common_failure("TaskPersonalAcceptanceRequired",task_command_offer(command).id);return common_success();}
Status task_personal_acceptance_original_start_gate(const CommonStore& c,const TaskState& tasks,const TaskCatalog& catalog,const TaskPersonalAcceptanceCatalog* selected,const TaskPersonalAcceptanceServices* services,const ActionCoreView& action,const TaskCommand& command,const TaskQuote& quote){const bool personal=command.source_kind==std::optional<StableId>{task_personal_acceptance_source_kind};const auto* policy=selected&&(!command.offer_ref||command.offer_ref->kind==OfferRef::Kind::authored)?task_personal_acceptance_policy(*selected,task_command_offer(command).id):nullptr;if(!personal)return command.kind=="accept_offer"&&policy?common_failure("TaskPersonalAcceptanceRequired",policy->offer_id):common_success();if(!policy||!services||&services->sources.common!=&c||&services->sources.tasks!=&tasks||&services->sources.task_catalog!=&catalog||&services->sources.catalog!=selected||command.kind!="accept_offer"||action.kind!="accept_offer"||command.offer_ref||action.start_tick!=c.tick()||action.remaining_ticks!=1||quote.duration!=1||quote.task_id||quote.reward||!personal_acceptance_detail::narrative(command.context)||!personal_acceptance_detail::context(command.context,quote.context))return common_failure("TaskPersonalAcceptanceCandidateRequired",action.id);return validate_task_personal_acceptances(services->sources);}
bool task_personal_acceptance_can_interrupt(const StableId& code){return code=="TaskPersonalAcceptanceDeclarationChanged";}
}
